namespace sv_542212a3a9874eee8ef0fee08bc3c0fb;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

@* Displays current theme in the header top-row. *@

<span class="theme-indicator" style="color: @(Theme?.AccentColor ?? "#0d6efd");">
    @GetIcon() @(Theme?.Theme.ToString() ?? "Light")
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string GetIcon() => Theme?.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };
}

@* Quick toggle in the sidebar to cycle Light → Dark → System. *@
@rendermode InteractiveServer

@inject CascadingValueSource<ThemeInfo> ThemeSource

<div class="nav-item px-3 py-2">
    <button class="btn btn-sm btn-outline-secondary w-100" @onclick="CycleTheme">
        @GetIcon() @(Theme?.Theme.ToString() ?? "Light")
    </button>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private async Task CycleTheme()
    {
        var current = Theme ?? new ThemeInfo();
        current.Theme = current.Theme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };
        await ThemeSource.NotifyChangedAsync(current);
    }

    private string GetIcon() => Theme?.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };
}

@page "/settings"
@rendermode InteractiveServer

@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select" value="@currentTheme" @onchange="OnThemeChanged">
                @foreach (var t in Enum.GetValues<Theme>())
                {
                    <option value="@t">@t</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" class="form-control form-control-color"
                       value="@accentColor" @onchange="OnAccentChanged" />
                <span class="text-muted">@accentColor</span>
            </div>
        </div>

        <div class="mt-3 p-3 rounded" style="border: 2px solid @accentColor;">
            <strong>Preview:</strong> Mode = @currentTheme, Accent =
            <span style="color: @accentColor;">@accentColor</span>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private Theme currentTheme;
    private string accentColor = "#0d6efd";

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            currentTheme = Theme.Theme;
            accentColor = Theme.AccentColor;
        }
    }

    private async Task OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var parsed))
        {
            currentTheme = parsed;
            await ApplyChanges();
        }
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        accentColor = e.Value?.ToString() ?? "#0d6efd";
        await ApplyChanges();
    }

    private async Task ApplyChanges()
    {
        var updated = Theme ?? new ThemeInfo();
        updated.Theme = currentTheme;
        updated.AccentColor = accentColor;
        await ThemeSource.NotifyChangedAsync(updated);
    }
}

